\[(\alpha) =\frac{(1 + \sin x - \cos x)(1 + \sin x + \cos x)}{(1 + \sin x + \cos x)(1 + \sin x + \cos x)} \quad \mbox{multiply to RHS both sides by (1 + sin x + cos x)}\\ 
= \frac{1 + 2\sin x +\sin^2 x - \cos^2 x}{1 + 2\sin x + \sin^2 x + 2\cos x + \cos^2 x}
                                                             \mbox{expanding numerator and denomiator}\\
                              = \frac{1 + 2\sin x +\sin^2 x - 1 + \sin^2 x}{1 + 2\sin x + \sin^2 x + 2\cos x + 1 - \sin^2 x}
                                                             \mbox{since cos ^2 x - sin^2 x = cos 2x and  1 + sin ^2 x = 2}\\
                                                              = \frac{2 + 2\sin x}{2 + 2\sin x + 2 \cos x}
                                                              \mbox{分別合并分母和分子}\\              
                                                              = \frac{2(1 + \sin x)}{2(1 + \sin x + \cos x)}
                                                              = \frac{1}{1 + \cos(-x)} 
                                                              \mbox{since sin -x = sin x}\\
                                                              = \frac{1}{1 + \cos x}\\
                                                              \text{then we are done!}
